function fail(msg) { const err = new Error(msg); err.status = 400; throw err; }
function isBoolean(v) { return typeof v === 'boolean'; }
function validateConfig(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) fail('Buchkonfiguration fehlt.');
  const {way,format,binding,ink,paper,pages,qty}=raw;
  if (!Object.hasOwn(DIVISORS, way)) fail('Druckweg ungültig.');
  if (!['a5','pocket'].includes(format)) fail('Buchformat ungültig.');
  if (!['soft','hard'].includes(binding)) fail('Bindung ungültig.');
  if (!['bw','color'].includes(ink)) fail('Innendruck ungültig.');
  if (!Number.isInteger(pages) || !Number.isInteger(qty)) fail('Seitenzahl oder Auflage ungültig.');
  if (!QTY.includes(qty) || (way === 'sell' && qty < 50)) fail('Auflage ungültig.');
  if (format === 'a5') {
    if (!['115','135'].includes(paper) || pages < 48 || pages > 600 || (pages - 48) % 4 !== 0) {
      fail('DIN-A5-Papier oder Seitenzahl ungültig.');
    }
  } else {
    if (paper !== '60' || binding !== 'soft' || ink !== 'bw' || pages < 48 || pages > 608 || (pages - 48) % 8 !== 0) {
      fail('Diese Taschenbuchkonfiguration ist nicht verfügbar.');
    }
  }
  const extras = raw.extras;
  if (!extras || typeof extras !== 'object' || Array.isArray(extras) ||
      !['check','wrap','copy'].every(k => isBoolean(extras[k]))) {
    fail('Zusatzleistungen ungültig.');
  }
  if ((format === 'pocket' && extras.wrap) || (way !== 'sell' && extras.copy)) {
    fail('Nicht verfügbare Zusatzleistung gewählt.');
  }
  return {way,format,binding,ink,paper,pages,qty,extras:{check:extras.check,wrap:extras.wrap,copy:extras.copy}};
}
function priceFor(raw) {
  const c = validateConfig(raw);
  const qi = QTY.indexOf(c.qty);
  const pi = (c.pages - 48) / (c.format === 'pocket' ? 8 : 4);
  const gross = c.format === 'pocket'
    ? POCKET_WMD_GROSS_CENTS[pi]?.[qi]
    : (c.paper === '115' ? A5_115_WMD_GROSS_CENTS : A5_135_WMD_GROSS_CENTS)[c.binding]?.[c.ink]?.[pi]?.[qi];
  if (!Number.isSafeInteger(gross) || gross <= 0) fail('Kein geprüfter Originalpreis für diese Konfiguration.');
  // Exakt die identische Rundungsformel wie im freigegebenen V30-Frontend.
  const printCents = Math.round(gross * 100 / DIVISORS[c.way]);
  const extrasCents = (c.extras.check ? 2900 : 0) +
    (c.format === 'a5' && c.extras.wrap ? c.qty * 25 : 0) +
    (c.way === 'sell' && c.extras.copy ? 285 : 0);
  const totalCents = printCents + extrasCents;
  if (!Number.isSafeInteger(totalCents) || totalCents <= 0) fail('Berechneter Preis ungültig.');
  const orderProperties = {
    'Variante': c.way === 'sell' ? 'Mit Midlifeart verkaufen' : 'Für dich drucken',
    'Format': c.format === 'pocket'
      ? 'Taschenbuch 125 × 190 mm – Softcover · 60 g/m² Inhalt'
      : `A5 – ${c.binding === 'hard' ? 'Hardcover' : 'Softcover'} · ${c.paper} g/m² Inhalt · Mattfolie`,
    'Inhalt': c.ink === 'bw' ? 'Schwarz-Weiß' : 'Bunt',
    'Seitenanzahl': String(c.pages),
    'Bücheranzahl': String(c.qty),
    'Qualitätskontrolle': c.extras.check ? 'Ja' : 'Nein',
    'Einzeln einschweißen': (c.format === 'a5' && c.extras.wrap) ? 'Ja' : 'Nein'
  };
  if (c.way === 'sell') orderProperties['Autorenexemplar zusenden'] = c.extras.copy ? 'Ja' : 'Nein';
  return {
    config: c, wmdGrossCents: gross, printCents, extrasCents, totalCents,
    totalEuros: (totalCents / 100).toFixed(2),
    shippingRequired: c.way !== 'sell' || c.extras.copy,
    orderProperties
  };
}
module.exports = {priceFor,validateConfig};
